'use strict';
const $=id=>document.getElementById(id), C=LabCore;
let h=0,o=0,angle=104.5,yaw=.25,pitch=-.2,zoom=1,checked=false;
const canvas=$('molecule'),ctx=canvas.getContext('2d');
const state=()=>({hydrogen:h,oxygen:o,angleDegrees:angle,validation:C.validateWater(h,o,angle)});
function resize(c){const box=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=Math.round(box.width*dpr);c.height=Math.round(box.height*dpr);const context=c.getContext('2d');context.setTransform(dpr,0,0,dpr,0,0);return [box.width,box.height];}
function draw(){const [w,hh]=resize(canvas);ctx.clearRect(0,0,w,hh);const scale=Math.min(w/5.5,hh/4.2)*zoom;const project=p=>{let [x,y,z]=C.rotate(p,yaw,pitch),f=5/(5-z);return {x:w/2+x*scale*f,y:hh/2-y*scale*f+20,z,r:f};};
 ctx.strokeStyle='#dbe4d2';ctx.lineWidth=1;for(let i=-4;i<5;i++){let a=project([i,-1.35,-3]),b=project([i,-1.35,3]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();a=project([-4,-1.35,i]);b=project([4,-1.35,i]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}
 const base=C.waterPositions(angle),atoms=[];for(let i=0;i<o;i++)atoms.push({p:i===0?base[0]:[0,-1.5,i*.7],type:'O'});for(let i=0;i<h;i++)atoms.push({p:i<2?base[i+1]:[(i-2)*.8-.4,-1.6,0],type:'H'});
 if(o===1&&h===2){for(let i=1;i<=2;i++){const a=project(base[0]),b=project(base[i]);ctx.lineCap='round';ctx.strokeStyle='#aab5a0';ctx.lineWidth=15*zoom;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.strokeStyle='#e2e7d8';ctx.lineWidth=6*zoom;ctx.stroke();}}
 atoms.map(a=>({...a,...project(a.p)})).sort((a,b)=>a.z-b.z).forEach(a=>{let r=(a.type==='O'?35:25)*a.r*zoom;const grad=ctx.createRadialGradient(a.x-r*.35,a.y-r*.4,r*.05,a.x,a.y,r);if(a.type==='O'){grad.addColorStop(0,'#edb09b');grad.addColorStop(.5,'#c86f58');grad.addColorStop(1,'#8e3f32');}else{grad.addColorStop(0,'#ffffff');grad.addColorStop(.6,'#f2f4ec');grad.addColorStop(1,'#bdc9b3');}ctx.fillStyle=grad;ctx.shadowColor='#34462b33';ctx.shadowBlur=14;ctx.shadowOffsetY=10;ctx.beginPath();ctx.arc(a.x,a.y,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.fillStyle=a.type==='O'?'#fff9f4':'#455644';ctx.font=`600 ${Math.round(r*.6)}px Arial`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(a.type,a.x,a.y+1);});
}
function update(){ $('h-count').textContent=h;$('o-count').textContent=o;$('angle-value').textContent=angle.toLocaleString('ru-RU')+'°';$('empty-hint').hidden=h+o>0;$('formula').innerHTML=`H<sub>${h}</sub>O<sub>${o}</sub> <span> / состав модели</span>`;for(const b of document.querySelectorAll('[data-delta]')){const n=b.dataset.element==='h'?h:o;b.disabled=Number(b.dataset.delta)<0?n===0:n===4;}if(checked){const v=C.validateWater(h,o,angle);$('feedback').textContent=v.message;$('feedback').className=v.ok?'success':'error';$('result-text').textContent=v.ok?'Состав 2:1 · две связи O–H · угол '+angle.toLocaleString('ru-RU')+'°. Учебная модель воды.':'Модель пока не прошла проверку. '+v.message;}draw();}
for(const b of document.querySelectorAll('[data-element]'))b.addEventListener('click',()=>{const d=Number(b.dataset.delta);if(b.dataset.element==='h')h=Math.max(0,Math.min(4,h+d));else o=Math.max(0,Math.min(4,o+d));update();});
$('angle').addEventListener('input',e=>{angle=Number(e.target.value);update();});$('check').onclick=()=>{checked=true;update();};$('reset').onclick=()=>{h=o=0;angle=104.5;checked=false;$('angle').value=angle;$('feedback').className='';$('feedback').textContent='Добавьте 2 H и 1 O, затем проверьте модель.';$('result-text').textContent='Изменяйте состав и угол. Проверка поможет найти и исправить ошибку.';update();};$('home-view').onclick=()=>{yaw=.25;pitch=-.2;zoom=1;draw();};function setZoom(delta){zoom=Math.max(.65,Math.min(1.5,zoom+delta));draw();}$('zoom-out').onclick=()=>setZoom(-.1);$('zoom-in').onclick=()=>setZoom(.1);
let drag=null;canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.01;pitch=Math.max(-1.3,Math.min(1.3,pitch+(e.clientY-drag[1])*.01));drag=[e.clientX,e.clientY];draw();});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>drag=null);canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')yaw-=.15;if(e.key==='ArrowRight')yaw+=.15;if(e.key==='ArrowUp')pitch=Math.max(-1.3,pitch-.15);if(e.key==='ArrowDown')pitch=Math.min(1.3,pitch+.15);if(e.key==='+')setZoom(.1);if(e.key==='-')setZoom(-.1);draw();});
$('export').onclick=()=>{const result={project:'VR/AR Science Lab',model:'illustrative-browser-3d',...state(),checkedInInterface:checked,createdAt:new Date().toISOString()};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));a.href=url;a.download='science-lab-result.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};
let tab='chem';for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{tab=b.dataset.tab;for(const s of document.querySelectorAll('.tab'))s.hidden=s.id!==tab;for(const n of document.querySelectorAll('[data-tab]')){n.classList.toggle('active',n===b);n.setAttribute('aria-current',n===b?'page':'false');}if(tab==='chem')draw();if(tab==='phys')drawPendulum();};$('help').onclick=()=>$('guide').showModal();$('close-guide').onclick=()=>$('guide').close();
const descriptions={nucleus:'Ядро хранит основную часть ДНК и участвует в управлении работой клетки. Митохондрии также имеют собственную ДНК.',membrane:'Плазматическая мембрана отделяет клетку от среды и регулирует обмен веществ.',mitochondria:'Митохондрии участвуют в клеточном дыхании и синтезе АТФ.',cytoplasm:'Цитоплазма — внутренняя среда клетки вне ядра, содержащая органоиды. Здесь протекают многие реакции.'};for(const b of document.querySelectorAll('[data-org]'))b.onclick=()=>{$('org-info').textContent=descriptions[b.dataset.org];for(const n of document.querySelectorAll('[data-org]'))n.classList.toggle('selected',n===b);};$('bio-check').onclick=()=>{$('bio-feedback').textContent=$('bio-answer').value==='nucleus'?'Верно. Основная часть ДНК находится в ядре.':$('bio-answer').value?'Попробуйте ещё раз: найдите структуру, которая хранит основную часть ДНК.':'Сначала выберите ответ.';};
let length=1,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,t=0,last=0;$('pause').textContent=paused?'Продолжить':'Пауза';function drawPendulum(){if(tab!=='phys')return;const c=$('pendulum'),[w,hh]=resize(c),p=c.getContext('2d'),len=80+length*100,theta=Math.sin(t*2*Math.PI/C.period(length))*Math.PI/18,x=w/2+Math.sin(theta)*len,y=35+Math.cos(theta)*len;p.clearRect(0,0,w,hh);p.strokeStyle='#80967a';p.lineWidth=3;p.beginPath();p.moveTo(w/2-35,35);p.lineTo(w/2+35,35);p.moveTo(w/2,35);p.lineTo(x,y);p.stroke();p.fillStyle='#276b52';p.beginPath();p.arc(x,y,20,0,2*Math.PI);p.fill();p.font='14px Arial';p.textAlign='center';p.fillText('L = '+length.toLocaleString('ru-RU')+' м',w/2,hh-32);}
$('length').oninput=e=>{length=Number(e.target.value);$('length-value').textContent=length.toLocaleString('ru-RU',{minimumFractionDigits:2})+' м';$('period').textContent=C.period(length).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});drawPendulum();};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Продолжить':'Пауза';};function frame(now){if(last&&tab==='phys'&&!paused)t+=Math.min((now-last)/1000,.05);last=now;if(tab==='phys')drawPendulum();requestAnimationFrame(frame);}requestAnimationFrame(frame);new ResizeObserver(()=>{if(tab==='chem')draw();if(tab==='phys')drawPendulum();}).observe(document.querySelector('main'));update();
